import{i as e,n as t,o as n,r,t as i}from"./app-CKIWtCsy.js";var a=JSON.parse(`{"path":"/TeFWiki.html","title":"TeFWiki","lang":"en-US","frontmatter":{},"git":{"createdTime":1632739866000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":17}]},"readingTime":{"minutes":2.43,"words":728},"filePathRelative":"TeFWiki.md"}`),o={name:`TeFWiki.md`};function s(i,a,o,s,c,l){return n(),r(`div`,null,[...a[0]||=[e(`<h1 id="tefwiki" tabindex="-1"><a class="header-anchor" href="#tefwiki"><span>TeFWiki</span></a></h1><p>このWikiを作るのに使っている、自作のローカルWiki。mdのテキストファイルのWiki。 <a href="./Electron.html">Electron</a>版とAndroid版があって、<a href="./Syncthing.html">Syncthing</a>でデータを共有して使っている。サーバー要らず。</p><h2 id="関連リンク" tabindex="-1"><a class="header-anchor" href="#関連リンク"><span>関連リンク</span></a></h2><ul><li><a href="https://karino2.github.io/2021/04/17/tefwiki_ja.html" target="_blank" rel="noopener noreferrer">blog: TeFWiki：テキストファイルのmd+WikiLink</a><ul><li><a href="https://karino2.github.io/2021/04/10/TeFWiki.html" target="_blank" rel="noopener noreferrer">blog: TeFWiki、テキストファイルのWikiをElectronで作ってみる</a> 開発当初のブログ</li></ul></li><li><a href="https://github.com/karino2/TeFWiki-Electron" target="_blank" rel="noopener noreferrer">github:TeFWiki-Electron</a></li><li><a href="https://github.com/karino2/TeFWiki/" target="_blank" rel="noopener noreferrer">github:TeFWiki: TeFWiki for Android</a></li><li><a href="./Wikiとノート.html">Wikiとノート</a></li><li><a href="./サブWiki.html">サブWiki</a></li><li><a href="./講義ノート.html">講義ノート</a></li><li><a href="./MdImgr.html">MdImgr</a></li><li><a href="./Wikiのリンクを扱うシェルスクリプト.html">Wikiのリンクを扱うシェルスクリプト</a></li></ul><h2 id="コンセプト" tabindex="-1"><a class="header-anchor" href="#コンセプト"><span>コンセプト</span></a></h2><ul><li><a href="https://github.com/karino2/TeFWiki-Electron/blob/main/TeFWiki_concept.md" target="_blank" rel="noopener noreferrer">github: TeFWiki-Electron/TeFWiki_concept.md</a></li><li><a href="https://karino2.github.io/2021/04/17/tefwiki_ja.html" target="_blank" rel="noopener noreferrer">blog: TeFWiki：テキストファイルのmd+WikiLink</a></li></ul><p>プレーンテキストのmdにwikilinkをつけた物でいいんじゃないか。 フォルダの中身をまるごとGoogle Driveに突っ込めば共有出来るような感じに。</p><p>データさえあれば、アプリは各環境で作ればいいだろう、と思う。</p><h3 id="サーバーでは無くフォルダsyncの意義" tabindex="-1"><a class="header-anchor" href="#サーバーでは無くフォルダsyncの意義"><span>サーバーでは無くフォルダsyncの意義</span></a></h3><p>TeFWikiはサーバーを持たない。プレーンなフォルダをクラウドストレージ（やsyncthingsなど）で共有するだけ。 これはパーソナルなメモを保存するのにより適切と思う。</p><p>サーバーよりもクラウドストレージの方がデータの流出の可能性はずっと低いだろう。 それはサーバーがそのサービス用に作られるのに対し、クラウドストレージはもっと長い間開発と運用がされていて、セキュリティもずっと高い基準で運営されている事、サービスの性質として一般への公開がメインの仕事に入っていないのでよりセキュアに作りやすいという本質的な事情もあると思う。</p><p>サーバーはサービスを運営している人がprivacy policyを変えたり変な広告を入れたり、バグを入れたりして、乗り換えたくなるような事情がたびたび発生する。 特にメモのように長生きするものは、必ずサービスの寿命よりも長生きする。 その都度メモを全部きっちり削除して乗り換え先に全部いい感じに乗り換えるのは結構かったるい。</p><p>フォルダのsyncならアカウントを新たにつくる必要も無いし、クラウドストレージをのりかえる時もそのまま乗り換え出来るし、 将来クラウドストレージと違う技術になってもきっとフォルダをそのまま移動する方法は有り続けるだろう。</p><h3 id="アプリで無くファイルが主役" tabindex="-1"><a class="header-anchor" href="#アプリで無くファイルが主役"><span>アプリで無くファイルが主役</span></a></h3><p>TeFWikiは<a href="https://obsidian.md/" target="_blank" rel="noopener noreferrer">Obsidian</a>とコンセプト的には近いと思うし、実際Obsidanがもっと小さくてオープンソースでいい感じのモバイルアプリを提供していたら、自分で作らなかったかもしれない。 実際Obsidanでも良いと思う。</p><p>ただ根本的な所で違うな、と思うのは、Obsidanがプラグインという仕組みでアプリの中に世界を構築していこう、という所。 これは商売しようとしているのでこうなるのは理解出来る。</p><p>TeFWikiは逆に、ファイルを作りブラウズする為のアプリであって、それ以外の機能はこのアプリの外に作っていく事を期待して、 TeFWiki自体は必要最小限の機能に留めようとしている。 TeFWikiのファイルはTeFWIki以外のアプリやUnixコマンドなどでも作り編集されていく事を期待している。</p><p>実際自分はjekyllのブログのファイルをハードリンクで貼ってTeFWIkiのデータにしていたりもするし、 <a href="./いつなに.html">いつなに</a>も勝手にマークダウンを編集していく。 また、マークダウンのエディタとしても外部エディタとして<a href="./MDTouch.html">MDTouch</a>（PCでは<a href="./MDMinaosi.html">MDMinaosi</a>）をちょくちょく使っている。</p><p>例えばPC側はelispやvim scriptの拡張で同じデータを作っていっても、問題無くAndroid版アプリと組み合わせて使える、 というような、開かれたメモ環境を指向している。</p><p>アプリの中にいろんな機能を実装していくんじゃなくて、プレーンなファイルとディレクトリがあって、 それに対していろんなアプリを作っていく、という、よりUnix的なアプローチになっている。 これは、メモのファイルはTeFWikiよりも長生きする、という信念のもと、メモがTeFWikiに依存するのでは無く、TeFWikiはメモを作り出す為に今たまたま使っているアプリに過ぎない、というスタンスの違い。 この辺はコンセプトのリンク先にも書いてある。</p><h2 id="開発リンク" tabindex="-1"><a class="header-anchor" href="#開発リンク"><span>開発リンク</span></a></h2><ul><li><a href="https://bulma.io/documentation/columns/" target="_blank" rel="noopener noreferrer">bulma</a></li><li><a href="https://nodejs.org/api/fs.html" target="_blank" rel="noopener noreferrer">nodejs: fs</a></li><li><a href="https://github.com/jaredsburrows/gradle-license-plugin" target="_blank" rel="noopener noreferrer">jaredsburrows/gradle-license-plugin: Gradle plugin that provides a task to generate a HTML license report of your project.</a></li></ul><h2 id="リリース時のライセンス" tabindex="-1"><a class="header-anchor" href="#リリース時のライセンス"><span>リリース時のライセンス</span></a></h2><p>gradleのタスクでlicenseReleaseReportを実行してライセンス生成するとasset下が直接書き換わる。これにはbluma.cssなどが入らないのでimgs/js_licenses.txtの中身を足す事。</p><h2 id="そのうちやりたい事-2026-07-03-金" tabindex="-1"><a class="header-anchor" href="#そのうちやりたい事-2026-07-03-金"><span>そのうちやりたい事 2026-07-03 (金)</span></a></h2><p>欲しいと思った機能を書いておく。</p><ul><li>一番下、上へのスクロールボタン</li></ul><h2 id="mathサポート-どちらも" tabindex="-1"><a class="header-anchor" href="#mathサポート-どちらも"><span>Mathサポート (どちらも）</span></a></h2><p>ElectronもAndroid版もMathのサポートを入れた。 mathに関しては、インラインはドルの直後に空白があっては駄目そう。ドルとドルドルが動いている。</p><p><a href="https://github.com/karino2/TeFWiki-Electron/commit/9b9ee3fc557bd6b49e3be8bd2ab9845f3f0bc493" target="_blank" rel="noopener noreferrer">Math support by vscode/markdown-it-katex · karino2/TeFWiki-Electron@9b9ee3f</a></p><p><a href="https://github.com/microsoft/vscode-markdown-it-katex" target="_blank" rel="noopener noreferrer">microsoft/vscode-markdown-it-katex: Add Math to your Markdown with a KaTeX plugin for Markdown-it</a>を使っている。</p><p><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>f</mi><mi>x</mi></msub></mrow><annotation encoding="application/x-tex">f_x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">x</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>はインライン。</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>f</mi><mi>x</mi></msub></mrow><annotation encoding="application/x-tex">f_x </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">x</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></span></p><p>はブロック。</p><p>begin arrayとかもできそう。</p>`,35),t(`p`,{class:`katex-block`},[t(`span`,{class:`katex-display`},[t(`span`,{class:`katex`},[t(`span`,{class:`katex-mathml`},[t(`math`,{xmlns:`http://www.w3.org/1998/Math/MathML`,display:`block`},[t(`semantics`,null,[t(`mtable`,{rowspacing:`0.16em`,columnalign:`center`,columnspacing:`1em`},[t(`mtr`,null,[t(`mtd`,null,[t(`mstyle`,{scriptlevel:`0`,displaystyle:`false`},[t(`mi`,null,`y`)])]),t(`mtd`,null,[t(`mstyle`,{scriptlevel:`0`,displaystyle:`false`},[t(`mrow`,null,[t(`mo`,null,`=`),t(`mi`,null,`a`),t(`mi`,null,`x`)])])])]),t(`mtr`,null,[t(`mtd`,null,[t(`mstyle`,{scriptlevel:`0`,displaystyle:`false`},[t(`mrow`)])]),t(`mtd`,null,[t(`mstyle`,{scriptlevel:`0`,displaystyle:`false`},[t(`mrow`,null,[t(`mo`,null,`=`),t(`mn`,null,`2`)])])])])]),t(`annotation`,{encoding:`application/x-tex`},`\\begin{array}{c} y & = ax \\\\ & = 2 \\end{array}`)])])]),t(`span`,{class:`katex-html`,"aria-hidden":`true`},[t(`span`,{class:`base`},[t(`span`,{class:`strut`,style:{height:`2.4em`,"vertical-align":`-0.95em`}}),t(`span`,{class:`mord`},[t(`span`,{class:`mtable`},[t(`span`,{class:`arraycolsep`,style:{width:`0.5em`}}),t(`span`,{class:`col-align-c`},[t(`span`,{class:`vlist-t vlist-t2`},[t(`span`,{class:`vlist-r`},[t(`span`,{class:`vlist`,style:{height:`1.45em`}},[t(`span`,{style:{top:`-3.61em`}},[t(`span`,{class:`pstrut`,style:{height:`3em`}}),t(`span`,{class:`mord`},[t(`span`,{class:`mord mathnormal`,style:{"margin-right":`0.0359em`}},`y`)])]),t(`span`,{style:{top:`-2.41em`}},[t(`span`,{class:`pstrut`,style:{height:`3em`}}),t(`span`,{class:`mord`})])]),t(`span`,{class:`vlist-s`},`​`)]),t(`span`,{class:`vlist-r`},[t(`span`,{class:`vlist`,style:{height:`0.95em`}},[t(`span`)])])])]),t(`span`,{class:`arraycolsep`,style:{width:`0.5em`}}),t(`span`,{class:`arraycolsep`,style:{width:`0.5em`}}),t(`span`,{class:`col-align-c`},[t(`span`,{class:`vlist-t vlist-t2`},[t(`span`,{class:`vlist-r`},[t(`span`,{class:`vlist`,style:{height:`1.45em`}},[t(`span`,{style:{top:`-3.61em`}},[t(`span`,{class:`pstrut`,style:{height:`3em`}}),t(`span`,{class:`mord`},[t(`span`,{class:`mrel`},`=`),t(`span`,{class:`mspace`,style:{"margin-right":`0.2778em`}}),t(`span`,{class:`mord mathnormal`},`a`),t(`span`,{class:`mord mathnormal`},`x`)])]),t(`span`,{style:{top:`-2.41em`}},[t(`span`,{class:`pstrut`,style:{height:`3em`}}),t(`span`,{class:`mord`},[t(`span`,{class:`mrel`},`=`),t(`span`,{class:`mspace`,style:{"margin-right":`0.2778em`}}),t(`span`,{class:`mord`},`2`)])])]),t(`span`,{class:`vlist-s`},`​`)]),t(`span`,{class:`vlist-r`},[t(`span`,{class:`vlist`,style:{height:`0.95em`}},[t(`span`)])])])]),t(`span`,{class:`arraycolsep`,style:{width:`0.5em`}})])])])])])])],-1),e(`<h2 id="wikinameの絞り込みオープン-electron版のみ、途中-2026-07-28-火" tabindex="-1"><a class="header-anchor" href="#wikinameの絞り込みオープン-electron版のみ、途中-2026-07-28-火"><span>WikINameの絞り込みオープン(Electron版のみ、途中） 2026-07-28 (火)</span></a></h2><p>とりあえず動く所までは実装したが、矢印キーやC-fとのバインドなどやりたい事が残っている状態でCopilotのトークンが尽きたので続きは次回。 バックリンクは<a href="./SAF.html">SAF</a>では遅そうなのでAndroidでは実装しないが、絞り込みオープンは実装したい。ただこちらは後回しかな。</p><h3 id="android版もサポート-2026-08-01-土" tabindex="-1"><a class="header-anchor" href="#android版もサポート-2026-08-01-土"><span>Android版もサポート 2026-08-01 (土)</span></a></h3><p>ファイル名の絞り込み検索をAndroid版にも入れた。 実装してみたらめちゃ遅かったのでいろいろ<a href="./SAF.html">SAF</a>周りの高速化も入れた。</p><h2 id="バックリンクのサポート-electron版のみ-2026-07-25-土" tabindex="-1"><a class="header-anchor" href="#バックリンクのサポート-electron版のみ-2026-07-25-土"><span>バックリンクのサポート(Electron版のみ） 2026-07-25 (土)</span></a></h2><p><a href="./RandomThoughts.html">RandomThoughts</a>のバックリンクサポートがいい感じだったので、TeFWikiのElectron版もバックリンクをサポートしてみた。</p><p>Android版も欲しいけれど<a href="./SAF.html">SAF</a>は遅いので使い物になるか自信が無かったので必要になるまでやらない。</p><h2 id="インライン画像サポート-2025-08-19-火" tabindex="-1"><a class="header-anchor" href="#インライン画像サポート-2025-08-19-火"><span>インライン画像サポート 2025-08-19 (火)</span></a></h2><p><a href="./【書籍】魔法の人物ドローイング.html">【書籍】魔法の人物ドローイング</a>などのお絵描き系ハウツーをやるにあたり、画像のインライン表示を対応する事にする。</p><p>ただフォルダを掘ったり画像を置いたりは<a href="./MdImgr.html">MdImgr</a>でやる事にして、 TeFWikiとしては相対パスの画像を表示する、というだけにする。</p><p>TeFWikiは実際にファイルオープンをそのまま使うのでは無くサブWikiの外には出られないように自分でどこのファイルを開くかを管理しているので、 画像もmarkdown-itで相対パスのインラインイメージを <code>tefwikimg://</code> にしてElectronのカスタムスキーム対応で手で取得している。</p><p>Android版もほぼ同じ構成で、WebViewのinterceptでSAFにつなげる。ファイル権限無しで動くのは正しいAndroidアプリって感じだぜ。</p><h3 id="electron版で外部からのファイルopen依頼-2025-10-18-土" tabindex="-1"><a class="header-anchor" href="#electron版で外部からのファイルopen依頼-2025-10-18-土"><span>Electron版で外部からのファイルopen依頼 2025-10-18 (土)</span></a></h3><p>検索が欲しくなったが、アプリの中に実装したくはない。 そこで外部から相対パスでWikiNameを指定するとそれを開くようにしたい。</p><p>geminiに聞いたらsetAsDefaultProtocolClientを使え、というのでぐぐってみたら以下にあたる。</p><p><a href="https://www.electronjs.org/docs/latest/tutorial/launch-app-from-url-in-another-app" target="_blank" rel="noopener noreferrer">Deep Links - Electron</a></p><p>試してみよう。</p><p>以下で開けるようになった。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">% open &quot;tefwiki://open?path=RandomThoughts/TeFWiki.md&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>よしよし。 あとは<a href="./guash.html">guash</a>を使って、以下みたいにすればいいな。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">#!/usr/bin/env guash</span>
<span class="line"></span>
<span class="line">ls -t  ~/work/syncthing_dirs/TeFWiki/RandomThoughts/*.md | guash_filter &quot;Select Dest&quot;</span>
<span class="line">RES=($(guash_doquery))</span>
<span class="line">test $? -ne 0 &amp;&amp; exit 1</span>
<span class="line"></span>
<span class="line">FNAME=$(basename \${RES[0]})</span>
<span class="line">open &quot;tefwiki://open?path=RandomThoughts/\${FNAME}&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>いい感じだ。</p><p>Windowsで動くかはちょっとまだ試してないが、まぁしばらくはMacでしか使わないので時が来るまではこのままでいいだろう。</p>`,23)]])}var c=i(o,[[`render`,s]]);export{a as _pageData,c as default};